def parse_json(json_str: str):
    """
    Parse a JSON string according to RFC 8259 without using the built‑in json module
    or eval. Returns the corresponding Python data structure or raises ValueError
    on any syntax error.
    """
    import re

    class _Parser:
        def __init__(self, s: str):
            self.s = s
            self.i = 0
            self.n = len(s)

        # ------------------------------------------------------------------ #
        # Public entry point
        # ------------------------------------------------------------------ #
        def parse(self):
            self._skip_ws()
            value = self._parse_value()
            self._skip_ws()
            if self.i != self.n:
                self._error("Extra data after valid JSON")
            return value

        # ------------------------------------------------------------------ #
        # Core parsing functions
        # ------------------------------------------------------------------ #
        def _parse_value(self):
            self._skip_ws()
            if self.i >= self.n:
                self._error("Unexpected end of input while expecting a value")

            ch = self.s[self.i]

            if ch == '"':
                return self._parse_string()
            if ch == '{':
                return self._parse_object()
            if ch == '[':
                return self._parse_array()
            if ch == 't':
                return self._match_literal('true', True)
            if ch == 'f':
                return self._match_literal('false', False)
            if ch == 'n':
                return self._match_literal('null', None)
            if ch == '-' or ch.isdigit():
                return self._parse_number()

            self._error(f"Invalid character '{ch}' at start of value")

        # ------------------------------------------------------------------ #
        # Objects and arrays
        # ------------------------------------------------------------------ #
        def _parse_object(self):
            self._expect('{')
            obj = {}
            self._skip_ws()
            if self._peek() == '}':
                self._expect('}')
                return obj

            while True:
                self._skip_ws()
                if self._peek() != '"':
                    self._error("Object keys must be strings")
                key = self._parse_string()
                self._skip_ws()
                self._expect(':')
                self._skip_ws()
                val = self._parse_value()
                # Overwrite duplicate keys instead of raising an error
                obj[key] = val
                self._skip_ws()
                ch = self._peek()
                if ch == '}':
                    self._expect('}')
                    break
                elif ch == ',':
                    self._expect(',')
                else:
                    self._error("Expected ',' or '}' in object")
            return obj

        def _parse_array(self):
            self._expect('[')
            arr = []
            self._skip_ws()
            if self._peek() == ']':
                self._expect(']')
                return arr

            while True:
                self._skip_ws()
                arr.append(self._parse_value())
                self._skip_ws()
                ch = self._peek()
                if ch == ']':
                    self._expect(']')
                    break
                elif ch == ',':
                    self._expect(',')
                else:
                    self._error("Expected ',' or ']' in array")
            return arr

        # ------------------------------------------------------------------ #
        # Strings
        # ------------------------------------------------------------------ #
        def _parse_string(self):
            self._expect('"')
            sb = []
            while True:
                if self.i >= self.n:
                    self._error("Unterminated string literal")
                ch = self.s[self.i]
                self.i += 1
                if ch == '"':
                    break
                if ch == '\\':
                    if self.i >= self.n:
                        self._error("Unterminated escape sequence")
                    esc = self.s[self.i]
                    self.i += 1
                    if esc == '"':
                        sb.append('"')
                    elif esc == '\\':
                        sb.append('\\')
                    elif esc == '/':
                        sb.append('/')
                    elif esc == 'b':
                        sb.append('\b')
                    elif esc == 'f':
                        sb.append('\f')
                    elif esc == 'n':
                        sb.append('\n')
                    elif esc == 'r':
                        sb.append('\r')
                    elif esc == 't':
                        sb.append('\t')
                    elif esc == 'u':
                        sb.append(self._parse_unicode_escape())
                    else:
                        self._error(f"Invalid escape character '\\{esc}'")
                elif ord(ch) < 0x20:
                    self._error("Control characters must be escaped in strings")
                else:
                    sb.append(ch)
            return ''.join(sb)

        def _parse_unicode_escape(self):
            if self.i + 4 > self.n:
                self._error("Incomplete \\uXXXX escape")
            hex_digits = self.s[self.i:self.i + 4]
            if not re.fullmatch(r'[0-9a-fA-F]{4}', hex_digits):
                self._error(f"Invalid Unicode escape '\\u{hex_digits}'")
            code_point = int(hex_digits, 16)
            self.i += 4

            # Handle surrogate pairs (RFC 8259 permits them)
            if 0xD800 <= code_point <= 0xDBFF:  # high surrogate
                if self.s[self.i:self.i + 2] != '\\u':
                    self._error("Expected low surrogate after high surrogate")
                self.i += 2
                low_hex = self.s[self.i:self.i + 4]
                if not re.fullmatch(r'[0-9a-fA-F]{4}', low_hex):
                    self._error(f"Invalid low surrogate '\\u{low_hex}'")
                low = int(low_hex, 16)
                if not (0xDC00 <= low <= 0xDFFF):
                    self._error("Invalid low surrogate range")
                self.i += 4
                code_point = 0x10000 + ((code_point - 0xD800) << 10) + (low - 0xDC00)

            return chr(code_point)

        # ------------------------------------------------------------------ #
        # Numbers
        # ------------------------------------------------------------------ #
        _NUMBER_RE = re.compile(r'-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?')

        def _parse_number(self):
            match = self._NUMBER_RE.match(self.s, self.i)
            if not match:
                self._error("Invalid number format")
            num_str = match.group(0)
            self.i = match.end()
            if '.' in num_str or 'e' in num_str or 'E' in num_str:
                try:
                    return float(num_str)
                except ValueError:
                    self._error(f"Cannot convert '{num_str}' to float")
            else:
                try:
                    return int(num_str)
                except ValueError:
                    self._error(f"Cannot convert '{num_str}' to int")

        # ------------------------------------------------------------------ #
        # Literals true / false / null
        # ------------------------------------------------------------------ #
        def _match_literal(self, literal: str, value):
            end = self.i + len(literal)
            if self.s[self.i:end] != literal:
                self._error(f"Expected literal '{literal}'")
            self.i = end
            return value

        # ------------------------------------------------------------------ #
        # Utility helpers
        # ------------------------------------------------------------------ #
        def _skip_ws(self):
            while self.i < self.n and self.s[self.i] in ' \t\n\r':
                self.i += 1

        def _peek(self):
            if self.i >= self.n:
                return ''
            return self.s[self.i]

        def _expect(self, ch: str):
            if self.i >= self.n or self.s[self.i] != ch:
                self._error(f"Expected character '{ch}'")
            self.i += 1

        def _error(self, msg: str):
            context_start = max(0, self.i - 10)
            context_end = min(self.n, self.i + 10)
            snippet = self.s[context_start:context_end].replace('\n', '\\n')
            raise ValueError(f"{msg} at position {self.i}: ...{snippet}...")

    return _Parser(json_str).parse()

