def parse_json(json_str: str):
    """
    Parse a JSON string according to RFC 8259 without using the built‑in json module.
    Returns the corresponding Python data structure (dict, list, str, int, float,
    bool, None). Raises ValueError on any syntax error.
    """
    class _Parser:
        def __init__(self, s: str):
            self.s = s
            self.i = 0
            self.n = len(s)

        # ---------- utilities ----------
        def _peek(self) -> str:
            return self.s[self.i] if self.i < self.n else ''

        def _consume(self, expected: str = None) -> str:
            if self.i >= self.n:
                raise ValueError("Unexpected end of input")
            ch = self.s[self.i]
            if expected is not None and ch != expected:
                raise ValueError(f"Expected '{expected}' but found '{ch}' at position {self.i}")
            self.i += 1
            return ch

        def _skip_ws(self):
            while self.i < self.n and self.s[self.i] in ' \t\n\r':
                self.i += 1

        # ---------- entry ----------
        def parse(self):
            self._skip_ws()
            if self.i >= self.n:
                raise ValueError("Empty JSON string")
            value = self._parse_value()
            self._skip_ws()
            if self.i != self.n:
                raise ValueError(f"Extra data after valid JSON at position {self.i}")
            return value

        # ---------- value ----------
        def _parse_value(self):
            self._skip_ws()
            ch = self._peek()
            if ch == '"':
                return self._parse_string()
            if ch == '{':
                return self._parse_object()
            if ch == '[':
                return self._parse_array()
            if ch in 'tfn':
                return self._parse_literal()
            if ch == '-' or ch.isdigit():
                return self._parse_number()
            raise ValueError(f"Unexpected character '{ch}' at position {self.i}")

        # ---------- literals ----------
        def _parse_literal(self):
            if self.s.startswith('true', self.i):
                self.i += 4
                return True
            if self.s.startswith('false', self.i):
                self.i += 5
                return False
            if self.s.startswith('null', self.i):
                self.i += 4
                return None
            raise ValueError(f"Invalid literal at position {self.i}")

        # ---------- numbers ----------
        def _parse_number(self):
            start = self.i
            # optional minus
            if self._peek() == '-':
                self._consume('-')
            # integer part
            if self._peek() == '0':
                self._consume('0')
            else:
                if not self._peek().isdigit():
                    raise ValueError(f"Invalid number at position {self.i}")
                while self._peek().isdigit():
                    self._consume()
            # fraction
            if self._peek() == '.':
                self._consume('.')
                if not self._peek().isdigit():
                    raise ValueError(f"Invalid fractional part at position {self.i}")
                while self._peek().isdigit():
                    self._consume()
            # exponent
            if self._peek() in ('e', 'E'):
                self._consume()
                if self._peek() in ('+', '-'):
                    self._consume()
                if not self._peek().isdigit():
                    raise ValueError(f"Invalid exponent at position {self.i}")
                while self._peek().isdigit():
                    self._consume()
            num_str = self.s[start:self.i]
            try:
                if any(c in num_str for c in '.eE'):
                    return float(num_str)
                return int(num_str)
            except ValueError:
                raise ValueError(f"Malformed number '{num_str}'")

        # ---------- strings ----------
        def _parse_string(self):
            self._consume('"')
            chars = []
            while True:
                if self.i >= self.n:
                    raise ValueError("Unterminated string literal")
                ch = self._consume()
                if ch == '"':
                    break
                if ch == '\\':
                    esc = self._consume()
                    if esc == '"':
                        chars.append('"')
                    elif esc == '\\':
                        chars.append('\\')
                    elif esc == '/':
                        chars.append('/')
                    elif esc == 'b':
                        chars.append('\b')
                    elif esc == 'f':
                        chars.append('\f')
                    elif esc == 'n':
                        chars.append('\n')
                    elif esc == 'r':
                        chars.append('\r')
                    elif esc == 't':
                        chars.append('\t')
                    elif esc == 'u':
                        hex_digits = self.s[self.i:self.i + 4]
                        if len(hex_digits) != 4 or not all(c in '0123456789abcdefABCDEF' for c in hex_digits):
                            raise ValueError(f"Invalid Unicode escape at position {self.i}")
                        chars.append(chr(int(hex_digits, 16)))
                        self.i += 4
                    else:
                        raise ValueError(f"Invalid escape character '\\{esc}' at position {self.i - 1}")
                elif ord(ch) < 0x20:
                    raise ValueError(f"Invalid control character in string at position {self.i - 1}")
                else:
                    chars.append(ch)
            return ''.join(chars)

        # ---------- arrays ----------
        def _parse_array(self):
            self._consume('[')
            self._skip_ws()
            arr = []
            if self._peek() == ']':
                self._consume(']')
                return arr
            while True:
                arr.append(self._parse_value())
                self._skip_ws()
                ch = self._peek()
                if ch == ',':
                    self._consume(',')
                    self._skip_ws()
                    continue
                if ch == ']':
                    self._consume(']')
                    break
                raise ValueError(f"Expected ',' or ']' in array at position {self.i}")
            return arr

        # ---------- objects ----------
        def _parse_object(self):
            self._consume('{')
            self._skip_ws()
            obj = {}
            if self._peek() == '}':
                self._consume('}')
                return obj
            while True:
                self._skip_ws()
                if self._peek() != '"':
                    raise ValueError(f"Object keys must be strings at position {self.i}")
                key = self._parse_string()
                self._skip_ws()
                if self._peek() != ':':
                    raise ValueError(f"Expected ':' after key in object at position {self.i}")
                self._consume(':')
                self._skip_ws()
                value = self._parse_value()
                obj[key] = value
                self._skip_ws()
                ch = self._peek()
                if ch == ',':
                    self._consume(',')
                    self._skip_ws()
                    continue
                if ch == '}':
                    self._consume('}')
                    break
                raise ValueError(f"Expected ',' or '}' in object at position {self.i}")
            return obj

    return _Parser(json_str).parse()

