def parse_json(json_str: str):
    """
    Parse a JSON string according to RFC 8259 without using the built‑in json module
    or eval. Returns the corresponding Python data structure or raises ValueError
    on any syntax error.
    """
    class JSONParser:
        def __init__(self, s: str):
            self.s = s
            self.i = 0
            self.n = len(s)

        # ---------- public ----------
        def parse(self):
            self._skip_ws()
            value = self._parse_value()
            self._skip_ws()
            if self.i != self.n:
                self._error("Extra data after valid JSON")
            return value

        # ---------- core parsers ----------
        def _parse_value(self):
            self._skip_ws()
            if self.i >= self.n:
                self._error("Unexpected end of input while expecting a value")

            ch = self.s[self.i]

            if ch == '"':
                return self._parse_string()
            if ch == '{':
                return self._parse_object()
            if ch == '[':
                return self._parse_array()
            if ch == 't':
                return self._match_literal('true', True)
            if ch == 'f':
                return self._match_literal('false', False)
            if ch == 'n':
                return self._match_literal('null', None)
            if ch == '-' or self._is_digit_ascii(ch):
                return self._parse_number()

            self._error(f"Invalid character '{ch}' at start of value")

        def _parse_object(self):
            obj = {}
            self.i += 1                     # skip '{'
            self._skip_ws()
            if self._peek() == '}':
                self.i += 1                 # empty object
                return obj

            while True:
                self._skip_ws()
                if self._peek() != '"':
                    self._error("Object keys must be strings")
                key = self._parse_string()
                self._skip_ws()
                if self._peek() != ':':
                    self._error("Missing ':' after object key")
                self.i += 1                 # skip ':'
                self._skip_ws()
                value = self._parse_value()
                obj[key] = value
                self._skip_ws()
                ch = self._peek()
                if ch == '}':
                    self.i += 1
                    break
                if ch != ',':
                    self._error("Expected ',' or '}' in object")
                self.i += 1                 # skip ','
            return obj

        def _parse_array(self):
            arr = []
            self.i += 1                     # skip '['
            self._skip_ws()
            if self._peek() == ']':
                self.i += 1                 # empty array
                return arr

            while True:
                self._skip_ws()
                arr.append(self._parse_value())
                self._skip_ws()
                ch = self._peek()
                if ch == ']':
                    self.i += 1
                    break
                if ch != ',':
                    self._error("Expected ',' or ']' in array")
                self.i += 1                 # skip ','
            return arr

        def _parse_string(self):
            self.i += 1                     # skip opening quote
            result = []
            while self.i < self.n:
                ch = self.s[self.i]
                if ch == '"':
                    self.i += 1
                    return ''.join(result)
                if ch == '\\':
                    self.i += 1
                    if self.i >= self.n:
                        self._error("Unterminated escape sequence in string")
                    esc = self.s[self.i]
                    if esc == '"':
                        result.append('"')
                    elif esc == '\\':
                        result.append('\\')
                    elif esc == '/':
                        result.append('/')
                    elif esc == 'b':
                        result.append('\b')
                    elif esc == 'f':
                        result.append('\f')
                    elif esc == 'n':
                        result.append('\n')
                    elif esc == 'r':
                        result.append('\r')
                    elif esc == 't':
                        result.append('\t')
                    elif esc == 'u':
                        hex_digits = self.s[self.i+1:self.i+5]
                        if len(hex_digits) != 4 or not all(c in "0123456789abcdefABCDEF" for c in hex_digits):
                            self._error("Invalid Unicode escape")
                        code_point = int(hex_digits, 16)
                        result.append(chr(code_point))
                        self.i += 4
                    else:
                        self._error(f"Invalid escape character '\\{esc}'")
                elif ord(ch) < 0x20:
                    self._error("Control characters not allowed in JSON strings")
                else:
                    result.append(ch)
                self.i += 1
            self._error("Unterminated string literal")

        def _parse_number(self):
            start = self.i

            # optional minus
            if self._peek() == '-':
                self.i += 1

            # integer part
            if self._peek() == '0':
                self.i += 1
            else:
                if not self._is_digit_ascii(self._peek()):
                    self._error("Invalid number")
                while self._is_digit_ascii(self._peek()):
                    self.i += 1

            # fraction part
            if self._peek() == '.':
                self.i += 1
                if not self._is_digit_ascii(self._peek()):
                    self._error("Fraction part requires at least one digit")
                while self._is_digit_ascii(self._peek()):
                    self.i += 1

            # exponent part
            if self._peek() in ('e', 'E'):
                self.i += 1
                if self._peek() in ('+', '-'):
                    self.i += 1
                if not self._is_digit_ascii(self._peek()):
                    self._error("Exponent part requires at least one digit")
                while self._is_digit_ascii(self._peek()):
                    self.i += 1

            num_str = self.s[start:self.i]
            try:
                if '.' in num_str or 'e' in num_str or 'E' in num_str:
                    return float(num_str)
                else:
                    return int(num_str)
            except ValueError:
                self._error(f"Invalid numeric literal '{num_str}'")

        # ---------- helpers ----------
        def _match_literal(self, literal: str, value):
            end = self.i + len(literal)
            if self.s[self.i:end] != literal:
                self._error(f"Expected literal '{literal}'")
            self.i = end
            return value

        def _skip_ws(self):
            while self.i < self.n and self.s[self.i] in ' \t\n\r':
                self.i += 1

        def _peek(self):
            return self.s[self.i] if self.i < self.n else ''

        def _is_digit_ascii(self, ch: str) -> bool:
            """Return True only for ASCII digits 0‑9."""
            return '0' <= ch <= '9'

        def _error(self, msg):
            raise ValueError(f"{msg} at position {self.i}")

    return JSONParser(json_str).parse()

